function validate([n, x, y]) {
  if (!Number.isInteger(n) || n < 2 || n > 100) return 'n is a whole number from 2 to 100.';
  if (!Number.isInteger(x) || x < 1 || x > n) return 'x must be a house number from 1 to n.';
  if (!Number.isInteger(y) || y < 1 || y > n) return 'y must be a house number from 1 to n.';
  return null;
}

