function countOfPairs(n, x, y) {
  const graph = Array.from({ length: n + 1 }, () => []);
  for (let house = 1; house < n; house++) {
    graph[house].push(house + 1);
    graph[house + 1].push(house);
  }
  if (x !== y) {
    graph[x].push(y);
    graph[y].push(x);
  }

  const result = new Array(n).fill(0);
  for (let start = 1; start <= n; start++) {
    const dist = new Array(n + 1).fill(-1);
    dist[start] = 0;
    const queue = [start];
    for (let head = 0; head < queue.length; head++) {
      const house = queue[head];
      for (const next of graph[house]) {
        if (dist[next] === -1) {
          dist[next] = dist[house] + 1;
          result[dist[next] - 1]++;
          queue.push(next);
        }
      }
    }
  }
  return result;
}

