function countOfPairs(n, x, y) {
  const result = new Array(n).fill(0);
  for (let a = 1; a <= n; a++) {
    for (let b = 1; b <= n; b++) {
      if (a === b) continue;
      const d = Math.min(Math.abs(a - b), Math.abs(a - x) + 1 + Math.abs(y - b), Math.abs(a - y) + 1 + Math.abs(x - b));
      result[d - 1]++;
    }
  }
  return result;
}

